        xmlAttrPtr attrp = (xmlAttrPtr) dom_object_get_node(obj);
        xmlChar *content;

        if (attrp == NULL) {
                php_dom_throw_error(INVALID_STATE_ERR, 0);
                return FAILURE;
        }

        if ((content = xmlNodeGetContent((xmlNodePtr) attrp)) != NULL) {
                ZVAL_STRING(retval, (char *) content);
                xmlFree(content);
        } else {
                ZVAL_EMPTY_STRING(retval);
        }

        return SUCCESS;

}

